const { capture: capturePassword, restore: restorePassword } = passwordFormObj;
const { capture: captureMfa, restore: restoreMfa } = mfaFormObj;

export const snapshot = {
  capture: () => ({
    profile: captureProfile(),
    password: capturePassword(),
    mfa: captureMfa()
  }),
  restore: (values) => {
    if (values.profile) restoreProfile(values.profile);
    if (values.password) restorePassword(values.password);
    if (values.mfa) restoreMfa(values.mfa);
  }
};
